"""Build static, Russian storefront. Standard library only; no network required."""
import hashlib, html, json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
esc=html.escape
products=json.loads((ROOT/'products.json').read_text())
def money(n): return f'{n:,}'.replace(',',' ')+' ₽'
def card(p):
 return f'''<article class="product-card" data-product="{p['id']}"><div class="product-media"><button class="product-open" data-view="{p['id']}" aria-label="Подробнее: {esc(p['title'])}"><img src="{p['image']}" alt="{esc(p['title'])}" width="600" height="700" loading="lazy" decoding="async"></button><button class="favorite" data-favorite="{p['id']}" aria-label="В избранное: {esc(p['title'])}" aria-pressed="false">♡</button>{'<span class="product-tag">Новинка</span>' if p['isNew'] else ''}</div><div class="product-meta"><span>{p['category']} · {p['material']}</span><h3><button data-view="{p['id']}">{esc(p['title'])}</button></h3><div class="product-bottom"><strong>{money(p['price'])}</strong><button class="add-small" data-add="{p['id']}" aria-label="В корзину: {esc(p['title'])}">В корзину <span aria-hidden="true">＋</span></button></div></div></article>'''
