 return f'''<a class="skip" href="#main">Перейти к содержимому</a><div class="topbar">Мебель, с которой хочется остаться дома <a href="room.html">Соберите свою комнату в 3D ↗</a></div><header class="header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="f Store — главная"><span class="brand-icon">f</span> Store<span class="brand-caption">мебель для жизни</span></a><button class="icon-button menu-toggle" data-action="menu" aria-expanded="false" aria-controls="main-nav" aria-label="Открыть меню">☰</button><nav id="main-nav" aria-label="Основная навигация">{''.join(f'<a href="{href}" '+('aria-current="page" ' if href==file else '')+f'>{label}</a>' for href,label in nav)}</nav><div class="header-actions"><button class="icon-button" data-action="account" aria-label="Мой профиль">{icon('user')}</button><button class="icon-button" data-action="favorites" aria-label="Избранное">{icon('heart')}<span data-count="favorites" class="badge" hidden>0</span></button><button class="icon-button" data-action="cart" aria-label="Корзина">{icon('bag')}<span data-count="cart" class="badge" hidden>0</span></button></div></div></header>'''
