 page=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f2ec"><meta name="description" content="f Store — мебель для жизни. Русскоязычный каталог, избранное, корзина и интерактивная 3D-комната."><title>{name} — f Store</title><link rel="icon" href="assets/home-imgCabinet.svg"><link rel="stylesheet" href="styles.css?v={version('styles.css')}"><script defer src="store.js?v={version('store.js')}"></script>{extra}</head><body>{header(file)}<main id="main">{body}</main>{footer()}</body></html>'''
 (ROOT/file).write_text(page+'\n')
